import React, { useState } from 'react';
import { useDropzone } from 'react-dropzone';
import { Upload, FileText, CheckCircle2, Target, BookOpen, Mail, Sparkles, Cpu, ShieldCheck, GitBranch, ArrowRight, Zap } from 'lucide-react';
import { useAnalyze } from '../hooks/useAnalyze';
import LoadingScreen from '../components/LoadingScreen';
import BackgroundEffects from '../components/BackgroundEffects';
import AiAgentsBar from '../components/AiAgentsBar';
import SharedProfilesExplorer from '../components/SharedProfilesExplorer';
import { useNavigate } from 'react-router-dom';

const Home = () => {
  const [file, setFile] = useState(null);
  const [jobDescription, setJobDescription] = useState('');
  const [showExplorer, setShowExplorer] = useState(false);

  const { analyze, loading, progress, currentStep } = useAnalyze();
  const navigate = useNavigate();

  const onDrop = (acceptedFiles) => {
    if (acceptedFiles.length > 0) {
      setFile(acceptedFiles[0]);
    }
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx']
    },
    maxFiles: 1
  });

  const handleAnalyze = () => {
    console.log('[DEBUG Home.js] "Analyze Resume & Verify Profile" button clicked!');
    if (!file) {
      console.warn('[DEBUG Home.js] Validation failed: No file uploaded.');
      alert('Please upload a resume (PDF or DOCX)');
      return;
    }

    if (!jobDescription.trim()) {
      console.warn('[DEBUG Home.js] Validation failed: Job description empty.');
      alert('Please enter a job description');
      return;
    }

    console.log('[DEBUG Home.js] Validation passed. Calling analyze() hook...');
    analyze(file, jobDescription);
  };

  const handleSelectMockProfile = (mockAnalysis) => {
    sessionStorage.setItem('analysisResult', JSON.stringify(mockAnalysis));
    navigate('/results');
  };

  if (loading) {
    return (
      <LoadingScreen
        progress={progress}
        currentStep={currentStep}
      />
    );
  }

  return (
    <div className="min-h-screen bg-bronze-900 text-bronze-100 relative overflow-hidden">
      {/* Dynamic Warm Particles Background & Lighting Orbs */}
      <BackgroundEffects />

      {/* Hero Section with 3D AI Core */}
      <div className="relative z-10 pt-12 pb-16 px-4">
        <div className="max-w-6xl mx-auto text-center">

          {/* Top Announcement Pill */}
          <div className="inline-flex items-center space-x-2 px-4 py-2 rounded-full glass-pill border border-gold-300/30 text-xs font-mono mb-8 shadow-gold-glow animate-float">
            <Sparkles className="w-4 h-4 text-gold-300 animate-spin-slow" />
            <span className="text-gold-300 font-semibold tracking-wide">
              SkillBridge AI v2.0 Platform Live
            </span>
            <span className="text-bronze-600">•</span>
            <span className="text-bronze-200">Autonomous Developer Verification Engine</span>
          </div>

          {/* Main Cinematic Title */}
          <h1 className="text-4xl sm:text-6xl lg:text-7xl font-heading font-extrabold tracking-tight mb-6 leading-none">
            Developer Intelligence. <br />
            <span className="bg-clip-text text-transparent bg-gradient-to-r from-bronze-100 via-gold-300 to-bronze-400 glow-text-gold">
              Verified by AI.
            </span>
          </h1>

          <p className="text-base sm:text-xl text-bronze-200 max-w-3xl mx-auto mb-10 font-sans leading-relaxed">
            Upload your resume, verify your GitHub repositories with real-time AI code analysis, calculate your Trust Score, and unlock targeted SkillSwap opportunities.
          </p>

          {/* 3D AI Core Visual Node Graphic */}
          <div className="relative max-w-3xl mx-auto my-12 py-8 flex items-center justify-center">

            {/* Pulsing Neural Rings */}
            <div className="absolute w-[340px] h-[340px] rounded-full border border-gold-300/25 animate-ping opacity-30" />
            <div className="absolute w-[440px] h-[440px] rounded-full border border-bronze-100/20 animate-pulse" />

            {/* Central Holographic Golden AI Core */}
            <div className="relative z-10 w-44 h-44 rounded-full bg-gradient-to-tr from-bronze-600 via-gold-300 to-bronze-950 p-[2px] shadow-gold-glow animate-float">
              <div className="w-full h-full bg-bronze-950 rounded-full flex flex-col items-center justify-center p-4 backdrop-blur-xl border border-gold-300/40">
                <Cpu className="w-12 h-12 text-gold-300 mb-2 animate-pulse" />
                <span className="text-[10px] font-mono text-gold-300 font-bold uppercase tracking-widest">
                  AI CORE v2.0
                </span>
                <span className="text-[9px] font-mono text-bronze-100 mt-0.5">
                  100% OPERATIONAL
                </span>
              </div>
            </div>

            {/* Floating Orbit Node 1: Resume Hologram */}
            <div className="absolute top-0 -left-4 sm:left-6 glass-card p-3 rounded-2xl border border-gold-300/30 flex items-center space-x-3 shadow-lg animate-float">
              <FileText className="w-5 h-5 text-gold-300" />
              <div className="text-left text-xs font-mono">
                <p className="font-bold text-bronze-100">Resume Parser</p>
                <p className="text-bronze-200 text-[10px]">Text & Metadata Extracted</p>
              </div>
            </div>

            {/* Floating Orbit Node 2: GitHub Repository Node */}
            <div className="absolute bottom-0 -right-4 sm:right-6 glass-card p-3 rounded-2xl border border-bronze-100/30 flex items-center space-x-3 shadow-lg animate-float-reverse">
              <GitBranch className="w-5 h-5 text-bronze-100" />
              <div className="text-left text-xs font-mono">
                <p className="font-bold text-bronze-100">GitHub Analyzer</p>
                <p className="text-bronze-200 text-[10px]">Code Evidence Verified</p>
              </div>
            </div>

            {/* Floating Orbit Node 3: Trust Score Ring */}
            <div className="absolute top-2 -right-4 sm:right-10 glass-card p-3 rounded-2xl border border-gold-300/30 flex items-center space-x-3 shadow-lg animate-float">
              <ShieldCheck className="w-5 h-5 text-gold-300" />
              <div className="text-left text-xs font-mono">
                <p className="font-bold text-bronze-100">Trust Engine</p>
                <p className="text-gold-300 text-[10px]">Score: 94.8% High</p>
              </div>
            </div>
          </div>

        </div>
      </div>

      {/* AI Agents Live Status Bar */}
      <AiAgentsBar />

      {/* Main Input Command Center */}
      <div className="max-w-6xl mx-auto px-4 pb-16 relative z-10">
        <div className="grid md:grid-cols-2 gap-8">

          {/* Futuristic Resume Upload Dropzone */}
          <div className="glass-card p-6 sm:p-8 rounded-3xl border border-bronze-100/15 shadow-2xl relative overflow-hidden group">

            {/* Scan Beam Effect */}
            <div className="absolute inset-0 bg-scanline-warm pointer-events-none opacity-40" />

            <h2 className="text-xl font-heading font-bold mb-4 flex items-center text-bronze-100">
              <Upload className="w-5 h-5 mr-3 text-gold-300" />
              1. Upload Developer Resume
            </h2>

            <div
              {...getRootProps()}
              className={`relative border-2 border-dashed rounded-2xl p-8 text-center cursor-pointer transition-all duration-300 overflow-hidden ${
                isDragActive
                  ? 'border-gold-300 bg-gold-300/10 shadow-gold-glow scale-[1.01]'
                  : 'border-bronze-100/20 bg-bronze-950/60 hover:border-gold-300/50 hover:bg-bronze-900/60'
              }`}
            >
              <input {...getInputProps()} />

              {file ? (
                <div className="flex flex-col items-center justify-center space-y-3 py-4">
                  <div className="p-4 rounded-2xl bg-gold-300/20 border border-gold-300/40 text-gold-300 shadow-gold-glow">
                    <FileText className="w-10 h-10" />
                  </div>
                  <div>
                    <p className="font-heading font-bold text-bronze-100 text-base">{file.name}</p>
                    <p className="text-xs font-mono text-gold-300 mt-1">
                      {(file.size / 1024).toFixed(1)} KB • Ready for Parsing
                    </p>
                  </div>
                  <span className="px-3 py-1 rounded-full text-xs font-mono bg-gold-300/20 text-gold-300 border border-gold-300/40">
                    ✓ File Validated
                  </span>
                </div>
              ) : (
                <div className="py-6 space-y-4">
                  <div className="w-16 h-16 rounded-2xl bg-gold-300/10 border border-gold-300/30 flex items-center justify-center mx-auto text-gold-300 group-hover:scale-110 transition-transform">
                    <Upload className="w-8 h-8" />
                  </div>

                  <div>
                    <p className="text-bronze-100 font-medium text-base">
                      {isDragActive
                        ? 'Drop your resume file here now...'
                        : 'Drag & drop your resume or click to browse'}
                    </p>
                    <p className="text-bronze-200 text-xs font-mono mt-2">
                      Supports PDF or DOCX formats (Up to 10MB)
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Job Description Text Area */}
          <div className="glass-card p-6 sm:p-8 rounded-3xl border border-bronze-100/15 shadow-2xl relative">
            <h2 className="text-xl font-heading font-bold mb-4 flex items-center text-bronze-100">
              <FileText className="w-5 h-5 mr-3 text-gold-300" />
              2. Target Job Description
            </h2>

            <div className="relative">
              <textarea
                value={jobDescription}
                onChange={(e) => setJobDescription(e.target.value)}
                placeholder="Paste the target job description here (e.g. Senior Full Stack Engineer requiring React, Node.js, Docker, PostgreSQL)..."
                className="w-full h-48 glass-input rounded-2xl p-4 text-bronze-100 placeholder-bronze-200/50 focus:outline-none resize-none font-sans text-sm leading-relaxed"
              />

              <div className="flex items-center justify-between text-xs font-mono text-bronze-200 mt-2 px-1">
                <span>Auto-Keyword Visualizer Active</span>
                <span className="text-gold-300">{jobDescription.length} characters</span>
              </div>
            </div>
          </div>

        </div>

        {/* Big Glow Analyze Action Button */}
        <div className="mt-10 text-center">
          <button
            onClick={handleAnalyze}
            disabled={!file || !jobDescription.trim()}
            className="group relative inline-flex items-center justify-center px-10 py-5 rounded-2xl font-heading font-extrabold text-lg text-bronze-950 bg-gradient-to-r from-gold-300 via-bronze-100 to-gold-400 disabled:opacity-40 disabled:cursor-not-allowed transition-all duration-300 hover:scale-[1.03] shadow-gold-glow overflow-hidden"
          >
            <Zap className="w-6 h-6 mr-3 text-bronze-950 group-hover:animate-bounce" />
            <span>Analyze Resume & Verify Profile</span>
            <ArrowRight className="w-5 h-5 ml-3 group-hover:translate-x-1 transition-transform" />
          </button>

          {/* Quick Dataset Explorer Trigger Button */}
          <div className="mt-6">
            <button
              onClick={() => setShowExplorer(!showExplorer)}
              className="inline-flex items-center space-x-2 text-xs font-mono text-gold-300 hover:text-bronze-100 underline underline-offset-4 transition-colors"
            >
              <Cpu className="w-4 h-4" />
              <span>{showExplorer ? 'Hide Shared Mock Dataset Explorer' : 'Explore 20 Shared Developer Mock Profiles & SkillSwap Pairs'}</span>
            </button>
          </div>
        </div>

        {/* Shared Mock Profiles Explorer Component */}
        {showExplorer && (
          <SharedProfilesExplorer onSelectProfile={handleSelectMockProfile} />
        )}

      </div>

      {/* AI Platform Capabilities Section */}
      <div className="max-w-6xl mx-auto px-4 pb-20 relative z-10">
        <div className="text-center mb-10">
          <h2 className="text-2xl sm:text-3xl font-heading font-bold text-bronze-100 mb-2">
            SkillBridge AI Platform Modules
          </h2>
          <p className="text-bronze-200 text-sm font-mono">
            Autonomous verification and intelligence capabilities
          </p>
        </div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-6">

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-gold-300/15 border border-gold-300/30 flex items-center justify-center mx-auto mb-4 text-gold-300">
              <CheckCircle2 className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-bronze-100 mb-2">ATS Verification</h3>
            <p className="text-bronze-200 text-xs leading-relaxed font-sans">
              Evaluates resume formatting, section detection, and keyword match percentages.
            </p>
          </div>

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-bronze-100/15 border border-bronze-100/30 flex items-center justify-center mx-auto mb-4 text-bronze-100">
              <Target className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-bronze-100 mb-2">Skill Verification</h3>
            <p className="text-bronze-200 text-xs leading-relaxed font-sans">
              Cross-checks claimed resume skills against real GitHub repositories and code commits.
            </p>
          </div>

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-gold-400/15 border border-gold-400/30 flex items-center justify-center mx-auto mb-4 text-gold-400">
              <BookOpen className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-bronze-100 mb-2">Gap Roadmap</h3>
            <p className="text-bronze-200 text-xs leading-relaxed font-sans">
              Generates customized learning milestones and curated resources for missing skills.
            </p>
          </div>

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-bronze-400/15 border border-bronze-400/30 flex items-center justify-center mx-auto mb-4 text-bronze-200">
              <Mail className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-bronze-100 mb-2">Cover Letter AI</h3>
            <p className="text-bronze-200 text-xs leading-relaxed font-sans">
              Generates tailored, high-converting cover letters matching target job descriptions.
            </p>
          </div>

        </div>
      </div>
    </div>
  );
};

export default Home;
